const TEXT = Object.fromEntries(LANGS.slice(1).map((l, i) => [l.id, Object.fromEntries(ROWS.map((r) => [r[0], r[i + 1]]))]));

let current = 'en';

export function setLang(id) { current = LANGS.some((l) => l.id === id) ? id : 'en'; }
export function lang() { return current; }

// Text in the current language (anything not in the table, such as a
// level's name or a number, comes back as it is).
export function tr(key, ...args) {
  if (typeof key !== 'string') return key;
  const table = TEXT[current];
  const s = (table && table[key]) || key;
  return args.length ? s.replace(/\{(\d)\}/g, (m, i) => (args[i] !== undefined ? args[i] : m)) : s;
}
